    ["GetTrainerServiceDescription(95)"] = "1: string An instant strike that causes 68 damage in addition to your normal weapon damage.  Awards 1 combo point.",
    ["GetTrainerServiceDescription(96)"] = "1: string Finishing move that causes damage per combo point, increased by Attack Power:\r\n   1 point  : 199-295 damage\r\n   2 points: 350-446 damage\r\n   3 points: 501-597 damage\r\n   4 points: 652-748 damage\r\n   5 points: 803-899 damage",
